// Modify only the ephemeral CI checkout; native iOS files are generated by Expo.
const fs = require('node:fs');
const config = JSON.parse(fs.readFileSync('app.json', 'utf8'));
const bundleIdentifier = process.env.IOS_BUNDLE_IDENTIFIER;
if (!bundleIdentifier || !/^[A-Za-z0-9-]+(?:\.[A-Za-z0-9-]+)+$/.test(bundleIdentifier)) {
  throw new Error('IOS_BUNDLE_IDENTIFIER must be an explicit reverse-DNS bundle ID');
}
const run = process.env.GITHUB_RUN_NUMBER;
const attempt = process.env.GITHUB_RUN_ATTEMPT;
if (!/^\d+$/.test(run || '') || !/^\d+$/.test(attempt || '')) {
  throw new Error('GitHub run number and attempt are required');
}
config.expo.ios.bundleIdentifier = bundleIdentifier;
// A distinct build number for each workflow run and retry; independent of EAS.
config.expo.ios.buildNumber = `${run}.${attempt}`;
fs.writeFileSync('app.json', JSON.stringify(config, null, 2) + '\n');
